*/
scwin.init_datefmt_cal_isuexerDd0 = function () { $c.date.checkCalendarFormat("cal_isuexerDd0", "yyyyMMdd"); };

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.getBdchrgInfo($c.util.getComponent('slc_bdchrgTpCd'));
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf20300.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_searchIsuInfoChgList();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.dmenus = undefined; try { scwin.dmenus = /* sdd-asis-lifecycle:begin dmenus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */{
        "bmenu":3
        ,"mmenu":9
    }/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf20300' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_datefmt_cal_tmpIsuexerDd();
        scwin.init_datefmt_cal_procsReqDd();
        scwin.init_datefmt_cal_isuexerDd0();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf20300.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_mpd_files_select_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
